    let save = self.i;
    self.i += 1;
    let lo = self.num();
    let r = if self.peek() == Some(',') {
        self.i += 1;
        let hi = self.num();
        (lo.unwrap_or(0), hi.unwrap_or(usize::MAX))
    } else {
        match lo {
            Some(n) => (n, n),
            None => {
                self.i = save;
                return Ok(None);
            }
        }
    };
    if self.peek() != Some('}') {
        self.i = save;
        return Ok(None);
    }
    self.i += 1;
    if r.1 < r.0 {
        return re_err(format!("min repeat greater than max repeat at position {}", save + 1));
    }
    r
}

